-- Unapplied forward-only migration for CPM window settlement.
ALTER TABLE channel_advertiser_debits MODIFY COLUMN publisher_status ENUM('pending','settled','window_pending') NOT NULL DEFAULT 'pending';
CREATE TABLE IF NOT EXISTS channel_cpm_window_payouts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,window_id BIGINT UNSIGNED NOT NULL,publisher_id BIGINT UNSIGNED NOT NULL,neutral_amount DECIMAL(20,8) NOT NULL,adjustment_amount DECIMAL(20,8) NOT NULL,final_amount DECIMAL(20,8) NOT NULL,source_key VARCHAR(191) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'planned',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_cpm_window_publisher(window_id,publisher_id),UNIQUE KEY uq_cpm_payout_source(source_key),CONSTRAINT fk_cpm_payout_window FOREIGN KEY(window_id) REFERENCES channel_cpm_settlement_windows(id)) ENGINE=InnoDB;
